Corresponding angles on parallel lines are **equal**.

[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]

\usetikzlibrary{angles,quotes}
\coordinate (La) at (-2.8,1.2);
\coordinate (Lb) at (2.8,1.2);
\coordinate (Ma) at (-2.8,-1.2);
\coordinate (Mb) at (2.8,-1.2);
\coordinate (Tt) at (1.7,2.4);
\coordinate (Tb) at (-1.7,-2.4);
\coordinate (P) at (intersection of La--Lb and Tb--Tt);
\coordinate (Q) at (intersection of Ma--Mb and Tb--Tt);
\draw (La) -- (Lb);
\draw (Ma) -- (Mb);
\draw (Tb) -- (Tt);
\draw[->] (1.85,1.2) -- (2.45,1.2);
\draw[->] (1.85,-1.2) -- (2.45,-1.2);
\pic[draw, "$a$", angle radius=0.6cm, angle eccentricity=1.9] {angle = Tt--P--La};
\pic[draw, "$a$", angle radius=0.6cm, angle eccentricity=1.9] {angle = Tt--Q--Ma};
\end{tikzpicture}
[/tikz]

